//! Per-character lyric timing generated by an external command (`tools/lrc_align`).
//!
//! The command from the settings (e.g. `lrc-align` or `python -m lrc_align --model medium`)
//! is run on a worker thread with the audio path and the `.lrc` path appended. It rewrites the
//! `.lrc` in place (keeping `.lrc.bak`); when it exits successfully the lyrics are reloaded.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::Duration;

use crossbeam_channel::{Receiver, TryRecvError};
use eframe::egui;
use lrc_player_application::infrastructure::lyrics::LyricsTimeline;

use crate::presentation::app::GuiApp;

/// A running alignment.
pub(crate) struct AlignJob {
    /// Track the job was started for (the result is ignored if another track plays).
    track: String,
    lrc: PathBuf,
    rx: Receiver<Result<String, String>>,
}

impl AlignJob {
    pub(crate) fn is_for(&self, track: &str) -> bool {
        self.track == track
    }
}

/// Splits a command line into program + arguments (double quotes group, `\"` escapes).
pub(crate) fn split_command(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut in_quotes = false;
    let mut has = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\\' if chars.peek() == Some(&'"') => {
                cur.push('"');
                chars.next();
                has = true;
            }
            '"' => {
                in_quotes = !in_quotes;
                has = true;
            }
            c if c.is_whitespace() && !in_quotes => {
                if has {
                    out.push(std::mem::take(&mut cur));
                    has = false;
                }
            }
            c => {
                cur.push(c);
                has = true;
            }
        }
    }
    if has {
        out.push(cur);
    }
    out
}

/// Last non-empty lines of a process output, for toasts.
fn tail(text: &str, lines: usize) -> String {
    let v: Vec<&str> = text.lines().map(str::trim).filter(|l| !l.is_empty()).collect();
    v[v.len().saturating_sub(lines)..].join("\n")
}

fn run(command: &[String], audio: &Path, lrc: &Path) -> Result<String, String> {
    let (program, args) = command.split_first().ok_or_else(|| "empty command".to_string())?;
    let mut cmd = Command::new(program);
    cmd.args(args).arg(audio).arg(lrc);
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x0800_0000;
        cmd.creation_flags(CREATE_NO_WINDOW);
    }
    let out = cmd.output().map_err(|e| format!("{program}: {e}"))?;
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    if out.status.success() {
        Ok(tail(&stdout, 1))
    } else {
        let detail = tail(&stderr, 3);
        Err(if detail.is_empty() { format!("exit status {}", out.status) } else { detail })
    }
}

impl GuiApp {
    /// Whether a timing job is running for the playing track.
    pub(crate) fn lyric_alignment_running(&self) -> bool {
        self.ui.align_job.as_ref().is_some_and(|j| j.is_for(&self.play_path))
    }

    /// Starts the external timing command for the playing track's selected `.lrc`.
    pub(crate) fn start_lyric_alignment(&mut self, ctx: &egui::Context) {
        let tr = self.tr();
        if self.ui.align_job.is_some() {
            self.toast_info(tr.t("toast.align_busy").to_string());
            return;
        }
        let command = split_command(&self.config.align_command);
        if command.is_empty() {
            self.toast_warning(tr.t("toast.align_no_command").to_string());
            return;
        }
        let Some(lrc) = self.selected_lyrics_index.and_then(|i| self.lyrics_candidates.get(i)).map(|c| c.path.clone())
        else {
            self.toast_warning(tr.t("toast.no_lyrics_file").to_string());
            return;
        };
        if self.play_path.is_empty() {
            return;
        }
        let audio = PathBuf::from(&self.play_path);
        let (tx, rx) = crossbeam_channel::bounded(1);
        let wake = ctx.clone();
        let (job_audio, job_lrc) = (audio.clone(), lrc.clone());
        let spawned = std::thread::Builder::new().name("lyric-align".into()).spawn(move || {
            let _ = tx.send(run(&command, &job_audio, &job_lrc));
            wake.request_repaint();
        });
        if let Err(e) = spawned {
            self.toast_error(tr.f("toast.align_failed", &[&e.to_string()]));
            return;
        }
        self.ui.align_job = Some(AlignJob { track: self.play_path.clone(), lrc, rx });
        self.toast_info(tr.t("toast.align_started").to_string());
    }

    /// Applies a finished timing job (called every frame).
    pub(crate) fn poll_lyric_alignment(&mut self, ctx: &egui::Context) {
        let Some(job) = &self.ui.align_job else { return };
        let result = match job.rx.try_recv() {
            Ok(r) => r,
            Err(TryRecvError::Empty) => {
                ctx.request_repaint_after(Duration::from_millis(500));
                return;
            }
            Err(TryRecvError::Disconnected) => Err("worker stopped".to_string()),
        };
        let job = self.ui.align_job.take().expect("checked");
        let tr = self.tr();
        match result {
            Ok(summary) => {
                // Reload the rewritten file if it still belongs to the playing track.
                if job.is_for(&self.play_path) {
                    if let Some(index) = self.lyrics_candidates.iter().position(|c| c.path == job.lrc) {
                        if let Ok(timeline) = LyricsTimeline::from_lrc(&job.lrc) {
                            let candidate = &mut self.lyrics_candidates[index];
                            candidate.timeline = Some(timeline);
                            candidate.error = None;
                            if self.selected_lyrics_index == Some(index) {
                                self.load_lyrics_file(index);
                            }
                        }
                    }
                }
                self.toast_success(tr.f("toast.align_done", &[&summary]));
            }
            Err(err) => self.toast_error(tr.f("toast.align_failed", &[&err])),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{split_command, tail};

    #[test]
    fn commands_split_on_spaces_and_respect_quotes() {
        assert_eq!(split_command("lrc-align"), vec!["lrc-align"]);
        assert_eq!(split_command("  python -m lrc_align  --model medium "), vec!["python", "-m", "lrc_align", "--model", "medium"]);
        assert_eq!(
            split_command(r#""C:\Program Files\Python\python.exe" -m lrc_align"#),
            vec![r"C:\Program Files\Python\python.exe", "-m", "lrc_align"]
        );
        assert_eq!(split_command(r#"echo \"a b\""#), vec!["echo", "\"a", "b\""]);
        assert_eq!(split_command(r#"x """#), vec!["x", ""]);
        assert!(split_command("   ").is_empty());
    }

    #[test]
    fn tail_keeps_the_last_lines() {
        assert_eq!(tail("a\n\nb\nc\n", 2), "b\nc");
        assert_eq!(tail("", 3), "");
    }

    /// Runs a real command end to end: the "aligner" rewrites the .lrc, the app reloads it.
    #[cfg(unix)]
    #[test]
    fn finished_job_reloads_the_lyrics() {
        use crate::presentation::app::tests::test_app;
        use eframe::egui;
        use lrc_player_application::infrastructure::lyrics::Lyrics;

        let dir = tempfile::tempdir().unwrap();
        let ctx = egui::Context::default();
        let mut app = test_app(&ctx, dir.path(), false);
        app.play_path = dir.path().join("song.flac").to_string_lossy().into_owned();
        let lrc = dir.path().join("song.lrc");
        std::fs::write(&lrc, "[00:01.00]あい\n[00:05.00]end\n").unwrap();
        app.set_lyrics_candidates(Lyrics::rank_candidates([lrc.clone()]));
        assert!(!app.loaded_timeline.as_ref().unwrap().has_karaoke() || app.config.estimate_karaoke);

        // A fake aligner: writes word timing into the .lrc given as the last argument.
        let script = dir.path().join("align.sh");
        std::fs::write(
            &script,
            "#!/bin/sh\nfor last; do :; done\nprintf '[00:01.00]<00:01.00>あ<00:01.50>い<00:02.00>\\n[00:05.00]end\\n' > \"$last\"\necho '1 lines aligned'\n",
        )
        .unwrap();
        app.config.align_command = format!("sh {}", script.display());
        app.start_lyric_alignment(&ctx);
        assert!(app.lyric_alignment_running());
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while app.ui.align_job.is_some() && std::time::Instant::now() < deadline {
            app.poll_lyric_alignment(&ctx);
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        assert!(app.ui.align_job.is_none());
        let line = &app.loaded_timeline.as_ref().unwrap().lines()[0];
        assert!(line.is_karaoke() && !line.estimated, "real timing loaded from the rewritten file");
        assert_eq!(line.segments[1].start_ms, 1_500);

        // A failing command reports an error and leaves the lyrics alone.
        app.config.align_command = r#"sh -c "echo boom >&2; exit 3""#.into();
        app.start_lyric_alignment(&ctx);
        while app.ui.align_job.is_some() {
            app.poll_lyric_alignment(&ctx);
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        assert!(app.ui.toasts.len() >= 2);
    }
}
